import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"Class: ChunkSampler","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: ChunkSampler"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/worldgen/classes/ChunkSampler"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/worldgen/classes/ChunkSampler"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/worldgen/src"}},"headers":[],"relativePath":"api/@jsprismarine/worldgen/classes/ChunkSampler.md","filePath":"api/@jsprismarine/worldgen/classes/ChunkSampler.md","lastUpdated":1794206055000}`),a={name:`api/@jsprismarine/worldgen/classes/ChunkSampler.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/worldgen</a> / ChunkSampler</p><h1 id="class-chunksampler" tabindex="-1">Class: ChunkSampler <a class="header-anchor" href="#class-chunksampler" aria-label="Permalink to “Class: ChunkSampler”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L79" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:79</a></p><p>Samples one chunk column: the final density per block, then the aquifer&#39;s verdict on what fills the positions the density leaves open.</p><p>26.3 moved the cell interpolation that used to live in this class into the <code>interpolated</code> density function, so there is no cell grid here any more. The overworld&#39;s <code>final_density</code> carries <code>cell_size_xz: 4</code> and <code>cell_size_y: 8</code>, and the generator reads it per block.</p><p>Block states come out as Java identifiers. Translating them to Bedrock belongs to <code>@jsprismarine/mapping</code>, so nothing in this package knows about the Bedrock palette.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new ChunkSampler</strong>(<code>randomState</code>, <code>options</code>): <code>ChunkSampler</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L115" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:115</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="randomstate" tabindex="-1">randomState <a class="header-anchor" href="#randomstate" aria-label="Permalink to “randomState”">​</a></h5><p><a href="./RandomState.html"><code>RandomState</code></a></p><h5 id="options" tabindex="-1">options <a class="header-anchor" href="#options" aria-label="Permalink to “options”">​</a></h5><p><a href="./../#chunksampleroptions"><code>ChunkSamplerOptions</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>ChunkSampler</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="cellcount" tabindex="-1">cellCount <a class="header-anchor" href="#cellcount" aria-label="Permalink to “cellCount”">​</a></h3><blockquote><p><code>readonly</code> <strong>cellCount</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L91" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:91</a></p><p>How many interpolation cells <a href="#foreachcellblock">ChunkSampler.forEachCellBlock</a> splits the chunk into.</p><p>One for a dimension whose density functions interpolate nothing, in which case that method walks the chunk column by column exactly as <a href="#fill">ChunkSampler.fill</a> does.</p><hr><h3 id="context" tabindex="-1">context <a class="header-anchor" href="#context" aria-label="Permalink to “context”">​</a></h3><blockquote><p><code>readonly</code> <strong>context</strong>: <a href="./SampleContext.html"><code>SampleContext</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L83" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:83</a></p><p>The per-chunk mutable state the compiled samplers read.</p><hr><h3 id="volume" tabindex="-1">volume <a class="header-anchor" href="#volume" aria-label="Permalink to “volume”">​</a></h3><blockquote><p><code>readonly</code> <strong>volume</strong>: <a href="./../#aquifervolume"><code>AquiferVolume</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L81" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:81</a></p><p>The block extent this sampler covers.</p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="aquifer" tabindex="-1">aquifer <a class="header-anchor" href="#aquifer" aria-label="Permalink to “aquifer”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>aquifer</strong>(): <a href="./../#aquifer"><code>Aquifer</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L182" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:182</a></p><p>The aquifer bound to this chunk, shared across every column in it.</p><p>Built on first use. Its constructor samples the preliminary surface height of 121 quart columns, which is 0.7 milliseconds that a sampler asked only for densities - a surface probe, a structure height walk - never has to spend.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><a href="./../#aquifer"><code>Aquifer</code></a></p><hr><h3 id="cellskipstats" tabindex="-1">cellSkipStats <a class="header-anchor" href="#cellskipstats" aria-label="Permalink to “cellSkipStats”">​</a></h3><h4 id="get-signature-1" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-1" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>cellSkipStats</strong>(): <code>Readonly</code>&lt;{ <code>aquiferCallsSkipped</code>: <code>number</code>; <code>blocksSkipped</code>: <code>number</code>; <code>cellsSkipped</code>: <code>number</code>; <code>densityCallsSkipped</code>: <code>number</code>; }&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L197" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:197</a></p><p>Counts the cells and per-block calls avoided by the proven-cell path.</p><h5 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h5><p><code>Readonly</code>&lt;{ <code>aquiferCallsSkipped</code>: <code>number</code>; <code>blocksSkipped</code>: <code>number</code>; <code>cellsSkipped</code>: <code>number</code>; <code>densityCallsSkipped</code>: <code>number</code>; }&gt;</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="blockat" tabindex="-1">blockAt() <a class="header-anchor" href="#blockat" aria-label="Permalink to “blockAt()”">​</a></h3><blockquote><p><strong>blockAt</strong>(<code>x</code>, <code>y</code>, <code>z</code>): <a href="./../#columnblock"><code>ColumnBlock</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L236" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:236</a></p><p>Returns the block at one position, running the density and then the aquifer.</p><p>Columns are generated from the top down because the aquifer&#39;s fluid update flag and its surface probing both assume that order.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y" tabindex="-1">y <a class="header-anchor" href="#y" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z" tabindex="-1">z <a class="header-anchor" href="#z" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#columnblock"><code>ColumnBlock</code></a></p><hr><h3 id="column" tabindex="-1">column() <a class="header-anchor" href="#column" aria-label="Permalink to “column()”">​</a></h3><blockquote><p><strong>column</strong>(<code>x</code>, <code>z</code>): <a href="./../#columnblock"><code>ColumnBlock</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L491" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:491</a></p><p>Generates one column from the top of the dimension down to its floor.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-1" tabindex="-1">x <a class="header-anchor" href="#x-1" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="z-1" tabindex="-1">z <a class="header-anchor" href="#z-1" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#columnblock"><code>ColumnBlock</code></a>[]</p><p>One entry per y level, ordered from <code>minBlockY</code> upward.</p><hr><h3 id="columntop" tabindex="-1">columnTop() <a class="header-anchor" href="#columntop" aria-label="Permalink to “columnTop()”">​</a></h3><blockquote><p><strong>columnTop</strong>(<code>x</code>, <code>z</code>, <code>accept</code>, <code>fromY?</code>): <code>number</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L271" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:271</a></p><p>The highest y in a column whose block a predicate accepts, or undefined for none.</p><p>This is the walk Java&#39;s <code>NoiseBasedChunkGenerator.iterateNoiseColumn</code> makes on behalf of <code>getBaseHeight</code>: the answer depends on the top of the column and nothing under it, so everything below the match goes unsampled. The blocks above it are sampled in the same order <a href="#column">ChunkSampler.column</a> uses, which is the order the aquifer expects.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-2" tabindex="-1">x <a class="header-anchor" href="#x-2" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="z-2" tabindex="-1">z <a class="header-anchor" href="#z-2" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h5 id="accept" tabindex="-1">accept <a class="header-anchor" href="#accept" aria-label="Permalink to “accept”">​</a></h5><p>(<code>state</code>) =&gt; <code>boolean</code></p><h5 id="fromy" tabindex="-1">fromY? <a class="header-anchor" href="#fromy" aria-label="Permalink to “fromY?”">​</a></h5><p><code>number</code> = <code>...</code></p><p>Where to start, for a caller whose dimension is shorter than the noise. Clamped to the top of the chunk.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code> | <code>undefined</code></p><hr><h3 id="density" tabindex="-1">density() <a class="header-anchor" href="#density" aria-label="Permalink to “density()”">​</a></h3><blockquote><p><strong>density</strong>(<code>x</code>, <code>y</code>, <code>z</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L212" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:212</a></p><p>The final density at one block position.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-3" tabindex="-1">x <a class="header-anchor" href="#x-3" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y-1" tabindex="-1">y <a class="header-anchor" href="#y-1" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z-3" tabindex="-1">z <a class="header-anchor" href="#z-3" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="fill" tabindex="-1">fill() <a class="header-anchor" href="#fill" aria-label="Permalink to “fill()”">​</a></h3><blockquote><p><strong>fill</strong>(): <a href="./../#columnblock"><code>ColumnBlock</code></a>[][][]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L507" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:507</a></p><p>Generates every column of the chunk.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#columnblock"><code>ColumnBlock</code></a>[][][]</p><p>A 16 by 16 grid indexed as <code>[localZ][localX]</code>, each entry a column ordered from <code>minBlockY</code> upward.</p><hr><h3 id="foreachcellblock" tabindex="-1">forEachCellBlock() <a class="header-anchor" href="#foreachcellblock" aria-label="Permalink to “forEachCellBlock()”">​</a></h3><blockquote><p><strong>forEachCellBlock</strong>(<code>cell</code>, <code>visit</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L297" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:297</a></p><p>Visits every block of one interpolation cell, top slab first.</p><p>A block is the same whichever order it is asked in, so this exists only to keep one interpolation cell current for 128 consecutive samples instead of eight. Walking the chunk column by column crosses a cell boundary every eight blocks and makes the density stack refetch eight cell corners each time; walking it cell by cell crosses one per cell.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="cell" tabindex="-1">cell <a class="header-anchor" href="#cell" aria-label="Permalink to “cell”">​</a></h5><p><code>number</code></p><p>A cell index below <a href="#cellcount">ChunkSampler.cellCount</a>. Indices run from the top of the dimension down, so a caller that stops early has filled the sky and not the bedrock.</p><h5 id="visit" tabindex="-1">visit <a class="header-anchor" href="#visit" aria-label="Permalink to “visit”">​</a></h5><p>(<code>x</code>, <code>y</code>, <code>z</code>, <code>state</code>, <code>scheduleFluidUpdate</code>) =&gt; <code>void</code></p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="foreachcolumnblock" tabindex="-1">forEachColumnBlock() <a class="header-anchor" href="#foreachcolumnblock" aria-label="Permalink to “forEachColumnBlock()”">​</a></h3><blockquote><p><strong>forEachColumnBlock</strong>(<code>x</code>, <code>z</code>, <code>visit</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L246" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:246</a></p><p>Visits a column from the top down without allocating one result object per block.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-4" tabindex="-1">x <a class="header-anchor" href="#x-4" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="z-4" tabindex="-1">z <a class="header-anchor" href="#z-4" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h5 id="visit-1" tabindex="-1">visit <a class="header-anchor" href="#visit-1" aria-label="Permalink to “visit”">​</a></h5><p>(<code>y</code>, <code>state</code>, <code>scheduleFluidUpdate</code>) =&gt; <code>void</code></p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="sample" tabindex="-1">sample() <a class="header-anchor" href="#sample" aria-label="Permalink to “sample()”">​</a></h3><blockquote><p><strong>sample</strong>(<code>node</code>, <code>x</code>, <code>y</code>, <code>z</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/4a5b3bcca8daa69c9551cfeb373515dc296b3c23/packages/worldgen/src/chunk/ChunkSampler.ts#L226" target="_blank" rel="noreferrer">chunk/ChunkSampler.ts:226</a></p><p>Samples one density function of this dimension at one block position.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="node" tabindex="-1">node <a class="header-anchor" href="#node" aria-label="Permalink to “node”">​</a></h5><p><a href="./../#densityfunctionnode"><code>DensityFunctionNode</code></a></p><h5 id="x-5" tabindex="-1">x <a class="header-anchor" href="#x-5" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y-2" tabindex="-1">y <a class="header-anchor" href="#y-2" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z-5" tabindex="-1">z <a class="header-anchor" href="#z-5" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p>`,162)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};